/* HubSystemMngMapper.selectCustomerCodeList : QnA 거래처 조회 */		
	SELECT CUSTOMER_CODE
	FROM TB_SMS_CUSTOMER 
	WHERE 1=1

		AND ENT_CODE = #{entCode}



			AND CUSTOMER_TYPE IN('HC','SC')
			AND (PARENT_CUSTOMER_CODE = #{ecmCustomerCode} OR CUSTOMER_CODE = #{ecmCustomerCode})


			AND CUSTOMER_TYPE = 'SC'
			AND CUSTOMER_CODE = #{ecmCustomerCode}

/* HubSystemMngMapper.selectQnAList : 문의사항(QnA) List */ SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT T1.REFERENCE_NO , T1.ENT_CODE , T1.CUSTOMER_CODE , (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{entCode} AND CUSTOMER_CODE = T1.CUSTOMER_CODE) AS CUSTOMER_NAME , T1.PO_NO , T1.HBL_NO , T1.QUESTION_USER_TYPE , T1.QUESTION_TYPE , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = T1.ENT_CODE AND GROUP_CODE = 'QUESTION_TYPE' AND CODE = T1.QUESTION_TYPE) AS QUESTION_TYPE_NAME , T1.EMERGENCY_YN , CASE WHEN T1.COMPLETE_YNH = 'Y' THEN '답변완료' WHEN T1.COMPLETE_YNH = 'H' THEN '대기' WHEN DT.QANDA_TYPE = 'A' THEN '답변확인요청' WHEN DT.QANDA_TYPE = 'Q' THEN '답변요청' WHEN T1.COMPLETE_YNH = 'N' THEN '답변요청' ELSE '' END AS COMPLETE_YNH , CASE WHEN DT.QANDA_TYPE = 'A' THEN DT.UPDATE_DATE_TIME ELSE NULL END AS ANSWER_DATE_TIME , T1.HOLD_REASON , T1.TITLE , T1.CONTENTS , T1.REGISTER_USER_ID , T1.REGISTER_DATE_TIME , T1.UPDATE_USER_ID , T1.UPDATE_DATE_TIME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = T1.ENT_CODE AND USER_ID = T1.REGISTER_USER_ID) AS REGISTER_USER_NAME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = T1.ENT_CODE AND USER_ID = T1.UPDATE_USER_ID) AS UPDATE_USER_NAME , OD.OD_JOB_NO , CASE WHEN FS.REFERENCE_NO_ID IS NOT NULL AND LTRIM(RTRIM(T1.FILE_TEMP_NAME)) != '' THEN 'Y' ELSE 'N' END AS FILE_SHARE FROM TB_ECM_QANDA T1 -- 최근 SEQ_NO를 먼저 찾고 LEFT JOIN LEFT JOIN ( SELECT D1.REFERENCE_NO, D1.QANDA_TYPE, D1.UPDATE_DATE_TIME, Latest.MIN_SEQ_NO FROM TB_ECM_QANDA_DETAIL D1 INNER JOIN ( SELECT REFERENCE_NO, MAX(SEQ_NO) AS MAX_SEQ_NO, CAST(MIN(SEQ_NO) AS VARCHAR) AS MIN_SEQ_NO FROM TB_ECM_QANDA_DETAIL GROUP BY REFERENCE_NO ) AS Latest ON D1.REFERENCE_NO = Latest.REFERENCE_NO AND D1.SEQ_NO = Latest.MAX_SEQ_NO ) AS DT ON T1.REFERENCE_NO = DT.REFERENCE_NO LEFT JOIN TB_COM_FILE_SHARE FS ON FS.FUNC_JOB_NO = T1.REFERENCE_NO AND FS.FUNC_REFERENCE_NO = DT.MIN_SEQ_NO OUTER APPLY ( SELECT TOP 1 OD.* FROM TB_ECM_OD OD WITH(NOLOCK) WHERE OD.PO_NO = T1.PO_NO ) AS OD WHERE T1.ENT_CODE = #{entCode} AND T1.CUSTOMER_CODE IN ('COUPANG-CN','COUPANG-US','COUPANG-JP','COUPANG-EU')
AND T1.${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND DT.${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND T1.${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND DT.${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND T1.PO_NO LIKE CONCAT('%',#{srchPoNo},'%')
AND T1.HBL_NO LIKE CONCAT('%',#{srchHblNo},'%')
AND T1.TITLE LIKE CONCAT('%',#{srchTitle},'%')
AND T1.QUESTION_TYPE = #{srchQuestionType}
AND DT.QANDA_TYPE = #{srchCompleteYnh}
AND T1.COMPLETE_YNH = #{srchCompleteYnh}
AND T1.CUSTOMER_CODE IN
#{item}
AND T1.CUSTOMER_CODE = #{srchBusinessType}
AND T1.CUSTOMER_CODE IN ('COUPANG-CN','COUPANG-US','COUPANG-JP','COUPANG-JP')

/* HubSystemMngMapper."selectQnASummary" : 문의사항(QnA) 미답변 건수 */ SELECT ISNULL(SUM(CASE WHEN ISNULL(DT.REFERENCE_NO,'')= '' and T1.QUESTION_USER_TYPE = 'S' THEN 1 ELSE 0 END),0) AS S_UNANSWERED_CNT, ISNULL(SUM(CASE WHEN ISNULL(DT.REFERENCE_NO,'')= '' and T1.QUESTION_USER_TYPE = 'C' THEN 1 ELSE 0 END),0) AS C_UNANSWERED_CNT FROM TB_ECM_QANDA T1 -- 최근 SEQ_NO를 먼저 찾고 LEFT JOIN LEFT JOIN ( SELECT D1.REFERENCE_NO, D1.QANDA_TYPE FROM TB_ECM_QANDA_DETAIL D1 INNER JOIN ( SELECT REFERENCE_NO, MAX(SEQ_NO) AS MAX_SEQ_NO FROM TB_ECM_QANDA_DETAIL GROUP BY REFERENCE_NO ) AS Latest ON D1.REFERENCE_NO = Latest.REFERENCE_NO AND D1.SEQ_NO = Latest.MAX_SEQ_NO ) AS DT ON T1.REFERENCE_NO = DT.REFERENCE_NO
WHERE T1.ENT_CODE = #{entCode}
AND T1.${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND T1.${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND T1.PO_NO LIKE CONCAT('%',#{srchPoNo},'%')
AND T1.CUSTOMER_CODE = #{srchCustomerCode}
AND T1.TITLE LIKE CONCAT('%',#{srchTitle},'%')
AND T1.QUESTION_TYPE = #{srchQuestionType}
AND T1.COMPLETE_YNH = #{srchCompleteYnh}
AND T1.CUSTOMER_CODE IN
#{item}

mapper.insert:
/* HubSystemMngMapper.insertQnA : 문의사항(QnA) Insert */

	SELECT 
		CONCAT(#{entCode},CONVERT(CHAR(6), GETDATE(), 112),'-',
			CONCAT(REPLICATE('0', 3 - LEN(A) ), A)
		)  AS REFERENCE_NO
	FROM 
	(SELECT 
		ISNULL((
				SELECT MAX(CEILING(SUBSTRING(REFERENCE_NO, 13, 3))) + 1 FROM TB_ECM_QANDA
				WHERE REFERENCE_NO LIKE CONCAT(#{entCode},CONVERT(CHAR(6), GETDATE(), 112),'%')								  
				), 1) AS A ) INFO


INSERT INTO TB_ECM_QANDA
(
	 REFERENCE_NO
	, ENT_CODE
	, CUSTOMER_CODE
	, CUSTOMER_NAME
	, PO_NO
	, HBL_NO
	, QUESTION_USER_TYPE
	, QUESTION_TYPE
	, EMERGENCY_YN
	, COMPLETE_YNH
	, HOLD_REASON
	, TITLE
	, CONTENTS
	,FILE_CONTENT_TYPE
	,FILE_PATH
	,FILE_TEMP_NAME
	,FILE_ORIGINAL_NAME
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
	,UPDATE_USER_ID
	,UPDATE_DATE_TIME
)
VALUES
(
	 #{referenceNo}
	,#{entCode}
	,#{customerCode}
	,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{entCode} AND CUSTOMER_CODE = #{customerCode})
	,#{poNo}
	,#{hblNo}
	,#{questionUserType}
	,#{questionType}
	,#{emergencyYn}
	,#{completeYnh}
	,#{holdReason}
	,#{title}
	,#{contents}
	,#{fileContentType}
	,#{filePath}
	,#{fileTempName}
	,#{fileOriginalName}
	,#{updateUserId}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	,#{updateUserId}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
)	

INSERT INTO TB_ECM_QANDA_DETAIL
(
	 REFERENCE_NO
	, ENT_CODE
	, SEQ_NO
	, QANDA_TYPE
	, QUESTION_SEQ_NO
	, CONTENTS
	,FILE_CONTENT_TYPE
	,FILE_PATH
	,FILE_TEMP_NAME
	,FILE_ORIGINAL_NAME
	,REGISTER_USER_ID
	,REGISTER_DATE_TIME
	,UPDATE_USER_ID
	,UPDATE_DATE_TIME
)
VALUES
(
	 #{referenceNo}
	,#{entCode}
	,#{seqNo}


			,'A'


			,'Q'





			, #{questionSeqNo}


			, NULL


	,#{contents}
	,#{fileContentType}
	,#{filePath}
	,#{fileTempName}
	,#{fileOriginalName}
	,#{updateUserId}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
	,#{updateUserId}
	,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
)

		/* HubSystemMngMapper.insertSubQnA : 문의사항(QnA) Insert */

        	SELECT ISNULL(MAX(SEQ_NO), 0) + 1 FROM TB_ECM_QANDA_DETAIL WHERE REFERENCE_NO = #{referenceNo}

		INSERT INTO TB_ECM_QANDA_DETAIL
		(
			 REFERENCE_NO
			, ENT_CODE
			, SEQ_NO
			, QANDA_TYPE
			, QUESTION_SEQ_NO
			, CONTENTS
			,FILE_CONTENT_TYPE
			,FILE_PATH
			,FILE_TEMP_NAME
			,FILE_ORIGINAL_NAME
			,REGISTER_USER_ID
			,REGISTER_DATE_TIME
			,UPDATE_USER_ID
			,UPDATE_DATE_TIME
		)
		VALUES
		(
			 #{referenceNo}
			,#{entCode}
			,#{seqNo}
			,#{qandaType}


					,NULL


					, #{questionSeqNo}


			,#{contents}
			,#{fileContentType}
			,#{filePath}
			,#{fileTempName}
			,#{fileOriginalName}
			,#{updateUserId}
			,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
			,#{updateUserId}
			,CONVERT(VARCHAR,DATEADD(hh, cast(#{gmtTime} AS int), GETDATE()), 20)
		)	



			UPDATE TB_ECM_QANDA SET 
					 COMPLETE_YNH = #{completeYnh}
					, HOLD_REASON = #{holdReason}
			WHERE ENT_CODE = #{entCode} 
			AND REFERENCE_NO = #{referenceNo}

