/* HubSystemMngMapper.selectSubQnADetail : 문의사항(QnA) - subGrid Data */ SELECT TOP 1 T1.REFERENCE_NO , T1.ENT_CODE , T1.CUSTOMER_CODE , (SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = #{entCode} AND CUSTOMER_CODE = T1.CUSTOMER_CODE) AS CUSTOMER_NAME , T1.PO_NO , T1.HBL_NO , T1.QUESTION_TYPE , T1.EMERGENCY_YN , T1.COMPLETE_YNH , T1.HOLD_REASON , T1.TITLE , D1.SEQ_NO , D1.QANDA_TYPE , D1.QUESTION_SEQ_NO , D1.CONTENTS , D1.FILE_CONTENT_TYPE , D1.FILE_PATH , D1.FILE_TEMP_NAME , D1.FILE_ORIGINAL_NAME
, D1.REGISTER_USER_ID , D1.REGISTER_DATE_TIME , D1.UPDATE_USER_ID , D1.UPDATE_DATE_TIME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = D1.ENT_CODE AND USER_ID = D1.REGISTER_USER_ID) AS REGISTER_USER_NAME , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = D1.ENT_CODE AND USER_ID = D1.UPDATE_USER_ID) AS UPDATE_USER_NAME -- 주문 정보 , OD.SHIPPER_NAME , OD.SHIPPER_TEL , OD.SHIPPER_HP , OD.CONSIGNEE_NAME_LOC AS CONSIGNEE_NAME , OD.CONSIGNEE_ADDRESS_LOC AS CONSIGNEE_ADDRESS , OD.CONSIGNEE_TEL , OD.CONSIGNEE_HP -- , (SELECT DETAIL_ITEM_NAME FROM TB_ECM_OD_ITEM item WHERE item.OD_JOB_NO = OD.OD_JOB_NO) AS ITEM_NAME -- , (SELECT PIECES FROM TB_ECM_OD_ITEM item WHERE item.OD_JOB_NO = OD.OD_JOB_NO) AS PIECES , (SELECT STUFF(( SELECT ', ' + item.DETAIL_ITEM_NAME + ' / ' + CAST(item.PIECES AS NVARCHAR) FROM TB_ECM_OD_ITEM item WHERE item.OD_JOB_NO = OD.OD_JOB_NO FOR XML PATH(''), TYPE ).value('.', 'NVARCHAR(MAX)'), 1, 2, '') ) AS ITEM_INFO
, OD.CUST_CODE_LV1 FROM TB_ECM_QANDA T1 LEFT JOIN TB_ECM_QANDA_DETAIL D1 ON T1.REFERENCE_NO = D1.REFERENCE_NO LEFT JOIN TB_ECM_OD od ON od.ENT_CODE = T1.ENT_CODE AND od.PO_NO = T1.PO_NO WHERE T1.ENT_CODE = #{entCode}
AND T1.CUSTOMER_CODE = #{customerCode}
AND T1.REFERENCE_NO = #{referenceNo}
AND D1.SEQ_NO = #{seqNo}

