	/* HubSystemMngMapper.insertQnafileShare : 파일등록 */

	SELECT ISNULL(MAX(REFERENCE_NO_ID), 0) + 1 
  	FROM TB_COM_FILE_SHARE


	INSERT INTO TB_COM_FILE_SHARE(			
		REFERENCE_NO_ID
		,ENT_CODE
		,ENT_BUSINESS_CODE
		,SOLUTION
		,FUNC_TYPE
		,FUNC_SUB_TYPE
		,FUNC_JOB_NO
		,FUNC_REFERENCE_NO
		,FILE_DOC_TYPE
		,FILE_NAME
		,FILE_EXT
		,FILE_SIZE
		,FILE_NAME_REMOTE
		,FILE_PATH_REMOTE
		,SHARE_YN
		,MEMO_DATE
		,FS_SERVER_TYPE
		,REGISTER_USER_ID
		,REGISTER_DATE_TIME
		,UPDATE_USER_ID
		,UPDATE_DATE_TIME
	)	
	VALUES(
		#{referenceNoId}
		,#{entCode}
		,#{entBusinessCode}
		,'ECM'
		,'OTHER'
		,'G'
		,#{funcJobNo}
		,#{funcReferenceNo}
		,'OT'
		,#{fileName}
		,#{fileExt}
		,#{fileSize}
		,#{fileNameRemote}
		,#{filePathRemote}
		,'Y'
		,DATEADD(HOUR, ${gmtTime}, GETDATE())
		,'WEB'
		,#{updateUserId}
		,DATEADD(HOUR, ${gmtTime}, GETDATE())
		,#{updateUserId}
		,DATEADD(HOUR, ${gmtTime}, GETDATE())
	)


		INSERT INTO TB_COM_FILE_SHARE_FILE(
			REFERENCE_NO_ID
			,SEQ_NO
			,FILE_DOC_TYPE
			,FILE_NAME
			,FILE_SIZE
			,FILE_NAME_REMOTE
			,FILE_PATH_REMOTE
		)VALUES

		(	
			#{referenceNoId}
		  , #{item.seqNo}
		  , #{item.fileDocType}
		  , #{item.fileName}
		  , #{item.fileSize}
		  , #{item.fileNameRemote}
		  , #{item.filePathRemote}
		)

		;
